-- Drops NorgannonDB lists and Icy Veins players recorded on Forever, for items the world has no source for
-- 2026_11_12_231_world_everlake_norgannondb_drops.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): allthethings 007a0073a43f4babfb7e, eg-link 9fcae73cc74fea4f1c4f, forever-db 67bf2ef637063d1a3963, foreverdb-net 2026-11-10.93d059be, item-history 8672fdc896ead1073a49, live-hotfixes 70862-a1137766129c, norgannondb a2a5bcf1031019093a3a, questiedb c0ce0c97ee449295ff1a, wago 1.60.1.70862, wowhead 2026-11-10, wowhead-tooltips parts/2026-11-10T133
-- Written against the fork world acore_world_dryrun.elstep_.
-- GPL-3.0: made from NorgannonDB (GPL-3.0; QuestieDB and pfQuest stock) and ForeverDB.net (Data from ForeverDB.net, GPL-3.0). Game names belong to Blizzard Entertainment. Icy Veins' WoW Forever database (db.icy-veins.com/wow-forever) witnesses rows and gives chances and prices.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- creature_loot_template: drops of items the world has no source for (only while the creature is spawned and alone on its own loot table, not where one of its reference tables already holds the item, and never again once added)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`Entry` int unsigned NOT NULL, `ItemType` tinyint NOT NULL, `Item` int unsigned NOT NULL, `Chance` float NOT NULL, `QuestRequired` tinyint(1) NOT NULL, `LootMode` smallint unsigned NOT NULL, `GroupId` tinyint unsigned NOT NULL, `MinCount` tinyint unsigned NOT NULL, `MaxCount` tinyint unsigned NOT NULL, `Comment` varchar(255), `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`Entry`, `ItemType`, `Item`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` t WHERE t.`Entry` = s.`Entry` AND t.`ItemType` = s.`ItemType` AND t.`Item` = s.`Item`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature_loot_template' AND r.`k1` = s.`Entry` AND r.`k2` = s.`ItemType` AND r.`k3` = s.`Item`) AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`Entry`) AND EXISTS (SELECT 1 FROM `creature_template_difficulty` d WHERE d.`Entry` = s.`Entry` AND d.`DifficultyID` = 0 AND d.`LootID` = s.`Entry`) AND NOT EXISTS (SELECT 1 FROM `creature_template_difficulty` d WHERE d.`LootID` = s.`Entry` AND d.`Entry` <> s.`Entry`) AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l JOIN `reference_loot_template` x ON x.`Entry` = l.`Item` WHERE l.`Entry` = s.`Entry` AND l.`ItemType` = 1 AND x.`ItemType` = 0 AND x.`Item` = s.`Item`);
DROP TEMPORARY TABLE `everlake_import_stage`;
